package kfc.service;
import kfc.database;import java.sql.*;import java.math.BigDecimal;import java.util.*;
public final class StockExtra {
 public static final class Line {public final String ma;public final BigDecimal sl,gia;public Line(String m,BigDecimal s,BigDecimal g){ma=m;sl=s;gia=g;}}
 public static void nhap(String ncc,List<Line> lines)throws SQLException{PhienQuanLy.yeuCauVaiTro("ADMIN","KHO");if(lines.isEmpty())throw new SQLException("Phiếu nhập trống");Set<String> ids=new HashSet<>();for(Line l:lines)if(!ids.add(l.ma)||l.sl.signum()<=0||l.sl.scale()>3||l.gia.signum()<0||l.gia.scale()>2)throw new SQLException("Dòng nhập sai hoặc trùng mã");KhoService.giaoDich(c->{int id;try(PreparedStatement p=c.prepareStatement("INSERT INTO phieu_nhap(MaNCC,NguoiNhap) VALUES(?,?)",Statement.RETURN_GENERATED_KEYS)){p.setString(1,ncc);p.setString(2,PhienQuanLy.taiKhoan());p.executeUpdate();try(ResultSet r=p.getGeneratedKeys()){if(!r.next())throw new SQLException("Không có mã phiếu");id=r.getInt(1);}}try(PreparedStatement p=c.prepareStatement("SET @kfc_reason=?")){p.setString(1,"Phiếu nhập PN"+id);p.execute();}try(PreparedStatement p=c.prepareStatement("INSERT INTO chi_tiet_phieu_nhap VALUES(?,?,?,?)");PreparedStatement u=c.prepareStatement("UPDATE ql_kho SET SoLuongTon=SoLuongTon+? WHERE MaNL=?")){for(Line l:lines){p.setInt(1,id);p.setString(2,l.ma);p.setBigDecimal(3,l.sl);p.setBigDecimal(4,l.gia);p.executeUpdate();u.setBigDecimal(1,l.sl);u.setString(2,l.ma);if(u.executeUpdate()!=1)throw new SQLException("Không có nguyên liệu "+l.ma);}}});}
}
